import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute } from '@angular/router';
import { FileService } from '../../core/services/file.service';

@Component({
  selector: 'app-prof-public',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './prof-public.component.html',
  styleUrls: ['./prof-public.component.scss']
})
export class ProfPublicComponent implements OnInit {
  slug = '';
  files: any[] = [];
  profName = '';

  constructor(private route: ActivatedRoute, private fileService: FileService) {}

  ngOnInit() {
    this.slug = this.route.snapshot.paramMap.get('slug') || '';
    this.profName = this.slug.split('-').map(s => s.charAt(0).toUpperCase() + s.slice(1)).join(' ');
    this.loadFiles();
  }
getTypeLabel(type: number): string {
  switch (type) {
    case 0: return 'Cours';
    case 1: return 'TD';
    case 2: return 'TP';
    case 3: return 'Autre';
    default: return 'Inconnu';
  }
}

  loadFiles() {
    if (!this.slug) return;
    this.fileService.getFilesByProf(this.slug).subscribe(res => this.files = res);
  }
}
<div class="public-container">

  <!-- 🧩 En-tête -->
  <section class="hero-section text-center py-5 bg-light mb-4">
    <h1 class="fw-bold text-primary">{{ profName }}</h1>
    <p class="text-muted mb-1">Espace pédagogique public</p>
    <small class="text-secondary">Cahiers de préparation et ressources partagées</small>
  </section>

  <!-- 🧾 Cahiers pédagogiques -->
  <section class="container mb-5">
    <h2 class="fw-bold mb-4 text-center">📖 Cahier de préparation pédagogique</h2>

    <!-- Liste des classes -->
    <div *ngFor="let c of classes" class="card mb-3 shadow-sm">
      <div class="card-body">
        <h4 class="fw-bold">{{ c.name }}</h4>

        <!-- Si un cahier existe -->
        <div *ngIf="c.cahier">
          <p class="text-muted small">
            <i class="bi bi-calendar-event me-1"></i>
            Mis à jour le {{ c.cahier.createdAt | date: 'dd MMM yyyy, HH:mm' }}
          </p>

          <a [href]="c.cahier.fileUrl" target="_blank" class="btn btn-outline-primary btn-sm">
            <i class="bi bi-download me-1"></i> Télécharger le cahier
          </a>
        </div>

        <!-- Sinon uploader un nouveau -->
        <div *ngIf="!c.cahier" class="mt-2">
          <label class="form-label small text-muted">Uploader le cahier (.pdf / .docx)</label>
          <input type="file" class="form-control mb-2" (change)="onFileSelected($event, c)">
          <button class="btn btn-primary btn-sm" (click)="uploadCahier(c)" [disabled]="uploadingId === c.id">
            <ng-container *ngIf="uploadingId !== c.id; else uploading">
              <i class="bi bi-cloud-upload me-1"></i> Envoyer
            </ng-container>
            <ng-template #uploading>
              <span class="spinner-border spinner-border-sm"></span> Upload...
            </ng-template>
          </button>
        </div>
      </div>
    </div>

    <div *ngIf="!classes.length" class="alert alert-info text-center">
      Aucune classe trouvée pour ce professeur.
    </div>
  </section>

</div>
